beforeExample:
package test;

import org.eclipse.jdt.internal.corext.dom.ASTNodes;
import org.eclipse.jdt.core.dom.ASTNode;
import org.eclipse.jdt.core.dom.Statement;
import org.eclipse.jdt.core.dom.Block;
import org.eclipse.jdt.core.dom.SwitchStatement;
import org.eclipse.jdt.core.dom.BodyDeclaration;

public class TestClass {
    ASTNode fieldReference;
    ASTNode[] selectedNodes;
    ASTNode startNode;

    void exampleMethod() {
        // Example 1
        BodyDeclaration enclosingBodyDeclaration = (BodyDeclaration)ASTNodes.getParent(selectedNodes[0], BodyDeclaration.class);

        // Example 2
        Statement origStmt = (Statement) ASTNodes.getParent(this.fieldReference, Statement.class);

        // Example 3
        if (startNode != null) {
            SwitchStatement block1 = (SwitchStatement)ASTNodes.getParent(startNode, SwitchStatement.class);
            Block block2 = (Block)ASTNodes.getParent(startNode, Block.class);
        }
    }
}

