negativeExample:
package test;

import org.eclipse.jdt.internal.corext.dom.ASTNodes;
import org.eclipse.jdt.core.dom.ASTNode;
import org.eclipse.jdt.core.dom.Statement;
import org.eclipse.jdt.core.dom.ExpressionStatement;

public class NegativeTestClass {
    ASTNode node;

    void anotherMethod() {
        // This cast is not redundant, as getParent returns ASTNode, not a specific type parameter
        Statement stmt = (Statement) node.getParent();

        // Different method entirely
        String str = (String) new Object();

        // Cast to supertype of return value (if getParent was specific)
        Object obj = (Object) ASTNodes.getParent(node, Statement.class);
    }
}
